import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Build the group
  const group = new THREE.Group();
  group.position.set(-3.2, 1, 0.06);
  group.rotation.order = 'YXZ';
  group.scale.set(1, 1, 1);

  // Create the plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Texture loading and material setup
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Track resources for cleanup
  const timelines = [];
  let textMesh = null;

  // Load the image texture asynchronously
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    texture.colorSpace = THREE.SRGBColorSpace;
    material.colorNode = new THREE.TextureNode(texture);
    material.needsUpdate = true;
  }).catch((err) => {
    console.warn('Failed to load image texture:', err);
  });

  // Render text content: "Features 1" as headline
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find(item => item.role === 'headline') || 
                       textItems[0] || 
                       { text: 'Features 1', role: 'headline', typography: { fontSize: 39 } };

  if (headlineItem && headlineItem.text) {
    const fontSize = headlineItem.typography?.fontSize ?? 39;
    // Convert px to scene units (approximate: 1 scene unit ≈ 100px)
    const sceneFontSize = fontSize / 100;

    textMesh = ctx.fontAtlas.createText(String(headlineItem.text), {
      fontSize: sceneFontSize,
      color: '#16161d', // ink
      align: 'center',
    });

    // Position text above or integrated with the plane
    textMesh.position.z = 0.1;
    group.add(textMesh);
  }

  // Initialize cleanup handler
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;
    geometry.dispose();
    material.dispose();
    if (textMesh) {
      textMesh.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
    }
  };

  return group;
}
